r<-'./TB_metabolome_exposome_20261115_2130';o<-'./系统复审与优化_20261116';z<-readRDS(file.path(r,'临床升级_双组学_20261116/output/analysis_data_private.rds'));a<-as.data.frame(z$data);fat<-unlist(z$mods,use.names=FALSE);module<-data.frame(variable=fat,module=rep(names(z$mods),lengths(z$mods)),definition='以组内浓度求和后取 log2；要求组内观测完整');module<-rbind(module,data.frame(variable='LBXET1',module='未纳入四个模块',definition='候选脂肪酸；原模块中未分配'));write.csv(module,file.path(o,'数据表/18_脂肪酸模块定义.csv'),row.names=FALSE);fat<-module$variable;mask<-a$adult&a$qvalid&!is.na(a$tst10)&is.finite(a$WTFAS2YR)&a$WTFAS2YR>0;mask[is.na(mask)]<-FALSE;fat<-fat[fat%in%names(a)];rows<-list();for(i in seq_along(fat))for(j in i:length(fat)){x<-a[[fat[i]]][mask];y<-a[[fat[j]]][mask];ok<-is.finite(x)&is.finite(y)&x>0&y>0;n<-sum(ok);r<-if(n>=10&&sd(log2(x[ok]))>0&&sd(log2(y[ok]))>0)cor(log2(x[ok]),log2(y[ok])) else NA;rows[[length(rows)+1]]<-data.frame(variable1=fat[i],variable2=fat[j],n=n,pearson_r_log2=r)};write.csv(do.call(rbind,rows),file.path(o,'数据表/19_脂肪酸相关性_未加权描述.csv'),row.names=FALSE);cat('pairwise',length(rows),'fatty acids',length(fat),'subset',sum(mask),'\n')
